import {resolveTakeClock,resolveTakeRate,takeRateAllowsDrop,takeClockSources,formatTakeTimecode,parseTakeTimecode} from './take-clock.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rates=[['','기준 FPS 따름'],['24000/1001','23.976 (24000/1001)'],['30000/1001','29.970 (30000/1001)'],['60000/1001','59.940 (60000/1001)'],['custom','직접 입력']];
export function takeClockMarkup(value,fps,disabled=false){const clock=resolveTakeClock(value),rate=resolveTakeRate(clock.rate??fps),key=clock.rate?rate.numerator+'/'+rate.denominator:'',selected=rates.some(([k])=>k===key)?key:'custom',lock=disabled?'disabled':'',dropAllowed=takeRateAllowsDrop(rate);return '<fieldset class="take-clock-fields"><legend>녹화 시계</legend><label>시간 기준<select data-take-clock="source" '+lock+'>'+takeClockSources.map(([key,label])=>'<option value="'+key+'" '+(key===clock.source?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>수집 FPS<select aria-label="수집 FPS" data-take-clock="rate" '+lock+'>'+rates.map(([k,label])=>'<option value="'+k+'" '+(k===selected?'selected':'')+' '+(k==='custom'&&selected!=='custom'?'disabled':'')+'>'+label+'</option>').join('')+'</select></label>'+('<label>분자 / 분모<input aria-label="수집 FPS 분수" data-take-clock="fraction" value="'+(clock.rate?rate.numerator+'/'+rate.denominator:'')+'" placeholder="'+fps+'/1" '+lock+' spellcheck="false"></label>')+'<label>드롭 프레임 표기<input data-take-clock="dropFrame" data-take-clock-locked="'+!dropAllowed+'" type="checkbox" '+(clock.dropFrame?'checked':'')+' '+(disabled||!dropAllowed?'disabled':'')+'></label><label>시작 타임코드<input aria-label="시작 타임코드" data-take-clock="timecode" value="'+esc(formatTakeTimecode(clock.startFrame,rate,clock))+'" '+lock+' spellcheck="false" placeholder="'+(clock.dropFrame?'00:00:00;00':'00:00:00:00')+'"></label><small class="take-rate-summary">수집 '+(rate.numerator/rate.denominator).toFixed(3)+' FPS · 편집 격자 '+fps+' FPS</small></fieldset>';}
export function takeClockInput(input,current,fps){const field=input.dataset.takeClock;if(!field)return null;const next=resolveTakeClock(current);if(field==='source')next.source=input.value;else if(field==='timecode')next.startFrame=parseTakeTimecode(input.value,next.rate??fps,next);else if(field==='dropFrame')next.dropFrame=input.checked;else if(field==='rate'){if(input.value===''){delete next.rate;delete next.dropFrame;}else if(input.value==='custom')next.rate=resolveTakeRate(next.rate??fps);else {if(!rates.some(([key])=>key===input.value))throw Error('수집 FPS를 확인하세요.');const [numerator,denominator]=input.value.split('/').map(Number);next.rate=resolveTakeRate({numerator,denominator});}if(next.dropFrame&&!takeRateAllowsDrop(next.rate??fps))next.dropFrame=false;}else if(field==='fraction'){if(!input.value.trim()){delete next.rate;delete next.dropFrame;return resolveTakeClock(next);}const match=/^(\d+)\s*\/\s*(\d+)$/.exec(input.value.trim());if(!match)throw Error('수집 FPS는 분자/분모로 입력하세요.');next.rate=resolveTakeRate({numerator:Number(match[1]),denominator:Number(match[2])});if(next.dropFrame&&!takeRateAllowsDrop(next.rate))next.dropFrame=false;}else throw Error('녹화 시계 필드를 확인하세요.');return resolveTakeClock(next);}
